python3 - <<'EOF'
import os
cands = {
    "WindowsTerminal候选1": "2eaca947-7f5f-4cfa-ba87-8f7fbeeef7be",
    "WindowsTerminal候选2": "e0bf52b6-9e35-4c2a-bb1c-4a4f4d3e1c2e",
    "conhost旧默认": "b23d10c0-e52e-411e-9d5b-c09fdf709c7d",
}
files = ["/mnt/c/Windows/System32/openconsole.exe",
         "/mnt/c/Windows/System32/conhost.exe"]
for f in files:
    if not os.path.exists(f):
        print(f, "不存在"); continue
    data = open(f, 'rb').read()
    print("=== ", f, f"(大小 {len(data)}) ===")
    for name, g in cands.items():
        ascii_form = g.encode('ascii')                          # 字符串形式
        utf16le_form = g.encode('utf-16-le')                     # 注册表字符串形式
        guid_bin = bytes.fromhex(g.replace('-', ''))             # 32字节 hex
        # 二进制 GUID（前3组小端）
        parts = g.split('-')
        le = bytes.fromhex(parts[0])[::-1] + bytes.fromhex(parts[1])[::-1] + bytes.fromhex(parts[2])[::-1] + bytes.fromhex(parts[3]) + bytes.fromhex(parts[4])
        res = []
        if ascii_form in data: res.append("ASCII字符串")
        if utf16le_form in data: res.append("UTF16LE字符串")
        if guid_bin in data: res.append("大端32hex")
        if le in data: res.append("小端GUID二进制")
        print(f"  {name} {g}: {res if res else '未找到'}")
EOF

